//! The PWA: the site installs on a phone's home screen, opens full screen like an app
//! and stays usable offline.
//!
//! - a manifest per language (`/{lang}/manifest.webmanifest`, and `/manifest.webmanifest`
//!   in French): the app installed from an English page opens in English; all share the
//!   same `id`, it is one application;
//! - a service worker (`/sw.js`), generated by `active::pwa`: pages go through the network
//!   first and the rest comes from the cache. Every page, the stylesheet, the fonts, the
//!   icons and the browser bundle are cached on the first visit, so the docs read and
//!   the playground translates without network; `/offline/` is shown otherwise.

use active::pwa::{Manifest, ServiceWorker};

use super::i18n::t;
use super::{BUNDLE_JS, BUNDLE_WASM, Site};
use crate::routes::{Lang, Page, Route, base, link};

/// The color of the site's background (`--bg`), shown around the app.
pub const THEME: &str = "#0d0b0a";

/// The address of the manifest of a language.
pub fn manifest_href(lang: Lang) -> String {
    link(&format!("/{}/manifest.webmanifest", lang.code()))
}

pub fn manifest(lang: Lang) -> Manifest {
    let b = base();
    Manifest::new("FerroSwift")
        .short_name("FerroSwift")
        .description(t(lang).home.description)
        .id(format!("{b}/"))
        .start_url(Route::new(lang, Page::Home).href())
        .scope(format!("{b}/"))
        .theme_color(THEME)
        .background_color(THEME)
        .lang(lang.code())
        .categories(["developer", "education", "productivity"])
        .icon(link("/static/icon-192.png"), "192x192", "image/png")
        .icon(link("/static/icon-512.png"), "512x512", "image/png")
        .maskable_icon(
            link("/static/icon-maskable-512.png"),
            "512x512",
            "image/png",
        )
        .icon(link("/favicon.svg"), "any", "image/svg+xml")
}

/// What is cached when the service worker installs: every page of the site, the offline
/// page, the stylesheet and the browser bundle (by their versioned address, as the pages
/// name them), the icons and the fonts.
pub fn precache(site: &Site) -> Vec<String> {
    let mut urls: Vec<String> = site.routes().iter().map(Route::href).collect();
    urls.push(link("/offline/"));
    for file in ["/static/app.css", BUNDLE_JS, BUNDLE_WASM] {
        if site.assets.get(file).is_some() {
            urls.push(site.assets.url(file));
        }
    }
    urls.push(link("/favicon.svg"));
    for icon in [
        "/static/icon-192.png",
        "/static/icon-512.png",
        "/static/icon-maskable-512.png",
        "/static/apple-touch-icon.png",
    ] {
        if site.assets.get(icon).is_some() {
            urls.push(link(icon));
        }
    }
    // The fonts, named by the stylesheet without a version.
    urls.extend(
        site.assets
            .iter()
            .map(|(url, _)| url)
            .filter(|url| url.starts_with("/static/fonts/") && url.ends_with(".woff2"))
            .map(link),
    );
    urls
}

pub fn worker(site: &Site) -> ServiceWorker {
    ServiceWorker::new("ferroswift-site", site.version())
        .precache(precache(site))
        .offline_page(link("/offline/"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_manifest_opens_the_page_language() {
        let json = manifest(Lang::En).to_json();
        assert!(json.starts_with(r#"{"name":"FerroSwift","short_name":"FerroSwift""#));
        assert!(json.contains(r#""start_url":"/en/""#));
        assert!(json.contains(r#""scope":"/""#) && json.contains(r#""id":"/""#));
        assert!(json.contains(r##""theme_color":"#0d0b0a""##));
        assert!(json.contains(r#""lang":"en""#));
        assert!(json.contains(r#""purpose":"maskable""#));
        assert_eq!(manifest_href(Lang::Fr), "/fr/manifest.webmanifest");
    }
}
